from pathlib import Path

INDEX=Path('archive-demo/index.html')
SW=Path('archive-demo/sw.js')
text=INDEX.read_text(encoding='utf-8')

def replace_line(prefix,new):
    global text
    lines=text.splitlines(); hits=[i for i,l in enumerate(lines) if l.startswith(prefix)]
    if len(hits)!=1: raise RuntimeError(f'{prefix}: {len(hits)} matches')
    lines[hits[0]]=new; text='\n'.join(lines)

def insert_after(prefix,block):
    global text
    lines=text.splitlines(); hits=[i for i,l in enumerate(lines) if l.startswith(prefix)]
    if len(hits)!=1: raise RuntimeError(f'{prefix}: {len(hits)} insert matches')
    lines[hits[0]+1:hits[0]+1]=block.splitlines(); text='\n'.join(lines)

def insert_before(prefix,block):
    global text
    lines=text.splitlines(); hits=[i for i,l in enumerate(lines) if l.startswith(prefix)]
    if len(hits)!=1: raise RuntimeError(f'{prefix}: {len(hits)} insert matches')
    lines[hits[0]:hits[0]]=block.splitlines(); text='\n'.join(lines)

