insert_after('function hasItemClaim(id){',r'''function archiveLevel(id){return Number(state.archive?.upgrades?.[id]||0)}function archiveTotal(){return Object.values(state.archive?.upgrades||{}).reduce((n,x)=>n+Number(x||0),0)}function itemSlotMax(){return 2+archiveLevel('armory')}function awardRes(n){const g=Math.max(0,Math.round((Number(n)||0)*(1+archiveLevel('gallery')*.1)));state.resonance+=g;return g}function relation(id){return Number(state.world.relationships[id]||0)}function adjustRelation(id,n){state.world.relationships[id]=clamp(relation(id)+(Number(n)||0),-100,100)}function faction(id){return Number(state.world.factions[id]||0)}function adjustFaction(id,n){state.world.factions[id]=clamp(faction(id)+(Number(n)||0),-100,100)}function standingLabel(n){return n>=35?'Trusted':n>=12?'Warm':n<=-35?'Hostile':n<=-12?'Cold':'Neutral'}function locKey(){return state.city&&state.location?state.city+'_'+state.location:''}function districtState(){const k=locKey();if(!k)return {heat:0,intel:0};if(!state.world.districts[k])state.world.districts[k]={heat:2,intel:0};return state.world.districts[k]}function currentSituationId(){return state.world.active[locKey()]?.id||null}function currentSituation(){const id=currentSituationId();return id?SITUATIONS[id]:null}function ensureSituation(){const k=locKey();if(!k||state.world.active[k])return;const next=(SITUATION_MAP[k]||[]).find(id=>!state.world.resolved.includes(id));state.world.active[k]=next?{id:next}:{id:null};save()}function requirementStatus(r){if(!r)return {ok:true,reason:''};if(r.claim&&!hasClaim(r.claim))return {ok:false,reason:'Requires claimed '+TEMPLATES[r.claim].name};if(r.item&&!hasItemClaim(r.item))return {ok:false,reason:'Requires '+CLAIM_ITEMS[r.item].name};if(r.met&&!state.metNPCs.includes(r.met))return {ok:false,reason:'Requires contact with '+NPCS[r.met].name};if(r.upgrade&&archiveLevel(r.upgrade)<1)return {ok:false,reason:'Requires '+ARCHIVE_UPGRADES[r.upgrade].name};return {ok:true,reason:''}}function applyEffects(fx){if(!fx)return;awardRes(fx.res||0);if(fx.faction)Object.entries(fx.faction).forEach(([id,v])=>adjustFaction(id,v));if(fx.relation)Object.entries(fx.relation).forEach(([id,v])=>adjustRelation(id,v));const d=districtState();d.heat=clamp(d.heat+(fx.heat||0),0,5);d.intel=clamp(d.intel+(fx.intel||0),0,5);if(fx.disc)addDisc(fx.disc[0],fx.disc[1],fx.disc[2]||'Intel')}function markSituationResolved(id){if(!state.world.resolved.includes(id))state.world.resolved.push(id);state.world.active[locKey()]={id:null}}function resolveSituationChoice(sid,cid){const sit=SITUATIONS[sid],ch=sit?.choices.find(x=>x.id===cid);if(!sit||!ch)return;const req=requirementStatus(ch.requires);if(!req.ok)return toast(req.reason);if(ch.combat)return encounterCombat(ch.combat,{type:'situation',sid,title:sit.title,win:ch.win||{},lose:{heat:1}});applyEffects(ch.fx||{});markSituationResolved(sid);state.lastResult=`<span class="tag">Decision</span><strong>${sit.title}</strong><br>${ch.label}. Your save now reflects that choice.`;log('Decision: '+sit.title+' — '+ch.label);save();render()}function resolveSituationCombat(ctx,won){if(!ctx||ctx.type!=='situation')return;applyEffects(won?(ctx.win||{}):(ctx.lose||{heat:1}));markSituationResolved(ctx.sid);ctx.resolutionText=won?`You resolved <strong>${ctx.title}</strong> on your terms.`:`<strong>${ctx.title}</strong> gets worse after the defeat.`;save()}function factionStrip(){return `<div class="worldStrip">${Object.entries(FACTION_NAMES).map(([id,n])=>{const v=faction(id);return `<span class="repChip ${v>=12?'good':v<=-12?'bad':''}">${n} ${v>0?'+':''}${v}</span>`}).join('')}</div>`}function buyArchiveUpgrade(id){const x=ARCHIVE_UPGRADES[id],l=archiveLevel(id);if(!x||l>=x.max)return toast('Already maxed');const c=x.costs[l];if(state.resonance<c)return toast('Need '+c+' Resonance');state.resonance-=c;state.archive.upgrades[id]=l+1;if(id==='manifest')state.manifestCapacityMax=50+(l+1)*10;log('Archive upgraded: '+x.name+' Lv.'+(l+1));save()}function recoveryOnReturn(){const n=archiveLevel('recovery')*20;if(!n)return;state.player.hp=Math.min(state.player.hpMax,state.player.hp+n);state.claimEnergy=Math.min(state.claimEnergyMax,state.claimEnergy+n)}function spriteSpec(c){if(c.uid==='jon'&&c.form!=='transform'){const a=ACCENTS[state.cosmetics.accent]||ACCENTS.violet,o=state.cosmetics.outfit,s1=o==='formal'?'#303440':o==='tactical'?'#37404b':a,s2=o==='formal'?a:o==='tactical'?a:'#d8dbe5';return [s1,s2,'normal',HAIRS[state.cosmetics.hair]||HAIRS.dark]}const p=SPRITE_PALETTE[c.templateId]||['#596174','#9ba5b9','normal'];return [p[0],p[1],p[2],'#24242b']}function combatSprite(c){const [s1,s2,k,h]=spriteSpec(c);return `<div class="spriteBox"><div class="spriteShadow"></div><div class="combatSprite ${k} ${c.anim||''}" style="--s1:${s1};--s2:${s2};--hair:${h}"><i class="head"></i><i class="body"></i><i class="arm l"></i><i class="arm r"></i><i class="leg l"></i><i class="leg r"></i></div></div>`}''')

replace_line('function questProgress(event,amount=1){',"function questProgress(event,amount=1){Object.entries(state.quests).forEach(([id,qs])=>{if(qs.status!=='active')return;const q=QUESTS[id],step=q.steps.find(s=>s.id===event);if(!step)return;qs.progress[event]=clamp((qs.progress[event]||0)+amount,0,step.need);if(q.steps.every(s=>(qs.progress[s.id]||0)>=s.need)){qs.status='complete';awardRes(q.reward.res||0);if(q.reward.item)state.inventory[q.reward.item]=(state.inventory[q.reward.item]||0)+(q.reward.qty||1);log('Quest complete: '+q.name);toast('Quest complete: '+q.name)}});save()}")
replace_line('function sceneSvg(kind){',"function sceneSvg(kind){if(kind==='archive'){const t=state.archive?.theme||'library',p={library:['#725bba','#d1af70'],tactical:['#354a67','#76a7ff'],neon:['#286a70','#75e7d2'],gallery:['#75465d','#f1c777']}[t]||['#725bba','#d1af70'],u=state.archive?.upgrades||{},rooms=`${u.manifest?'<circle cx=\"165\" cy=\"108\" r=\"32\" fill=\"none\" stroke=\"'+p[1]+'\" stroke-width=\"4\"/>':''}${u.armory?'<rect x=\"42\" y=\"120\" width=\"76\" height=\"56\" rx=\"8\" fill=\"#151b27\" stroke=\"'+p[1]+'\"/>':''}${u.recovery?'<rect x=\"575\" y=\"120\" width=\"50\" height=\"65\" rx=\"20\" fill=\"#13251f\" stroke=\"#70d8a4\"/>':''}${u.analysis?'<rect x=\"480\" y=\"45\" width=\"86\" height=\"50\" rx=\"7\" fill=\"#111e2d\" stroke=\"#75e7d2\"/>':''}${u.gallery?'<path d=\"M278 159h48l7 24h-62zM375 159h48l7 24h-62z\" fill=\"#251b23\" stroke=\"#f1c777\"/>':''}`;return `<svg viewBox=\"0 0 700 232\" preserveAspectRatio=\"none\"><defs><radialGradient id=\"a\"><stop stop-color=\"${p[0]}\"/><stop offset=\"1\" stop-color=\"#111522\"/></radialGradient></defs><rect width=\"700\" height=\"232\" fill=\"url(#a)\"/><path d=\"M0 178h700v54H0z\" fill=\"#090b11\"/>${rooms}<ellipse cx=\"350\" cy=\"98\" rx=\"95\" ry=\"108\" fill=\"none\" stroke=\"${p[1]}\" stroke-width=\"7\"/><ellipse cx=\"350\" cy=\"98\" rx=\"72\" ry=\"87\" fill=\"#070910\" opacity=\".86\"/></svg>`}if(kind==='gotham')return `<svg viewBox=\"0 0 700 232\" preserveAspectRatio=\"none\"><rect width=\"700\" height=\"232\" fill=\"#101828\"/><circle cx=\"560\" cy=\"52\" r=\"28\" fill=\"#aab8cf\" opacity=\".35\"/><path d=\"M0 166L65 122l40 28 52-82 47 90 72-122 58 129 63-86 58 92 45-46 54 45 46-84 70 92v54H0z\" fill=\"#0a0e17\"/></svg>`;return `<svg viewBox=\"0 0 700 232\" preserveAspectRatio=\"none\"><rect width=\"700\" height=\"232\" fill=\"#4d91da\"/><circle cx=\"585\" cy=\"46\" r=\"30\" fill=\"#fff1b4\" opacity=\".82\"/><path d=\"M0 184h700v48H0z\" fill=\"#182236\"/><path d=\"M55 184V90h65v94M145 184V56h80v128M250 184V110h60v74M338 184V42h78v142M445 184V82h72v102M545 184V62h96v122\" fill=\"#263b5a\"/></svg>`}")
replace_line('function header(){',"function header(){const used=manifestUsed(),max=state.manifestCapacityMax;return `<div class=\"topbar\"><div class=\"brand\"><small>Sovereign Archive</small><strong>${state.screen==='combat'?'Live Combat':state.city?CITY[state.city].name:'The Archive'}</strong></div><div class=\"topStat\">HP <b>${state.player.hp}</b></div><div class=\"topStat capacityHot\">M <b>${used}/${max}</b></div><div class=\"topStat\">CE <b>${state.claimEnergy}</b></div><div class=\"topStat\">R <b>${state.resonance}</b></div></div>`}")
replace_line('function render(){',"function render(){clearTimeout(autoTimer);document.body.className=state.city?CITY[state.city].theme:`archiveGlow archiveTheme-${state.archive.theme||'library'}`;if(state.screen==='combat')return renderCombat();app.innerHTML=header()+`<main class=\"main\">${state.screen==='archive'?archiveView():state.screen==='portal'?portalView():state.screen==='city'?cityView():locationView()}</main>`+nav();bindCommon();save()}")
replace_line('function archiveView(){',"function archiveView(){const used=manifestUsed(),cap=state.manifestCapacityMax,u=state.archive.upgrades;return `<section class=\"scene\">${sceneSvg('archive')}<div class=\"sceneShade\"></div><div class=\"sceneText\"><div class=\"eyebrow\">Home Space · ${ARCHIVE_THEMES[state.archive.theme]?.name||'Old Library'}</div><div class=\"sceneTitle\">The Archive</div><div class=\"sceneSub\">A place you are building, not just a menu. Rooms change what Jon can sustain, carry, predict, recover from, and display.</div></div></section><div class=\"section\">${factionStrip()}</div><div class=\"section\"><div class=\"stats\"><div class=\"stat\"><b>${state.claims.length}</b><span>Templates</span></div><div class=\"stat\"><b>${state.squad.length}</b><span>Bodies</span></div><div class=\"stat\"><b>${used}/${cap}</b><span>Manifest</span></div><div class=\"stat\"><b>${archiveTotal()}</b><span>Base Lvls</span></div></div></div><div class=\"section\"><div class=\"sectionTitle\"><h2>Archive Rooms</h2><span>Permanent progression</span></div><div class=\"archiveRooms\">${Object.entries(ARCHIVE_UPGRADES).map(([id,x])=>`<div class=\"roomCard\"><div class=\"roomLevel\">Lv ${u[id]||0}/${x.max}</div><div class=\"roomGlyph\">${x.glyph}</div><strong>${x.name}</strong><p>${x.effect(u[id]||0)}</p></div>`).join('')}</div></div><div class=\"section\"><div class=\"qolGrid\"><button class=\"btn primary\" data-upgrades>Upgrade Archive</button><button class=\"btn\" data-customize>Customize</button></div></div><div class=\"section\"><button class=\"choice\" data-go=\"portal\"><strong>Enter Portal Chamber</strong><p>Take the build you made here into Gotham or Metropolis.</p><span class=\"arrow\">›</span></button></div><div class=\"section\"><div class=\"card\"><div class=\"qolGrid\"><button class=\"btn good\" data-rest>Stabilize & Recover</button><button class=\"btn\" data-nav=\"claims\">Manage Manifestations</button></div></div></div><div class=\"section\"><div class=\"card systemCard\"><button class=\"btn danger\" data-newgame>Start New Game</button><div class=\"versionStamp\">Living Archive · v6</div></div></div>`}")
replace_line('function locationView(){',"function locationView(){ensureSituation();const l=CITY[state.city].locations[state.location],d=districtState(),sid=currentSituationId(),sit=currentSituation(),a=archiveLevel('analysis');const sh=sit?`<div class=\"section\"><div class=\"situationCard\"><div class=\"situationTag\">Active Situation</div><h3>${sit.title}</h3><p>${sit.text}</p><div class=\"decisionGrid\">${sit.choices.map(ch=>{const r=requirementStatus(ch.requires),exact=a>=2&&ch.combat?' · '+ch.combat.map(id=>TEMPLATES[id].name).join(' + '):'';return `<button class=\"decision\" data-situation=\"${sid}\" data-choice=\"${ch.id}\" ${!r.ok?'disabled':''}><strong>${ch.label}</strong><p>${r.ok?ch.desc:r.reason}</p>${a?`<div class=\"prediction\">${ch.predict||'Outcome depends on execution.'}${exact}</div>`:''}</button>`}).join('')}</div></div></div>`:`<div class=\"section\"><div class=\"card\"><strong>No major unresolved situation here.</strong><p class=\"tip\">The district still supports targeted operations rather than four identical encounter rolls.</p></div></div>`;return `<section class=\"scene\">${sceneSvg(state.city==='gotham'?'gotham':'metro')}<div class=\"sceneShade\"></div><div class=\"sceneText\"><div class=\"eyebrow\">${CITY[state.city].name}</div><div class=\"sceneTitle\">${l.name}</div><div class=\"sceneSub\">${l.desc}</div></div></section><div class=\"section\"><div class=\"districtBar\"><div class=\"districtStat\"><b>${d.heat}/5</b><span>Heat</span></div><div class=\"districtStat\"><b>${d.intel}/5</b><span>Intel</span></div><div class=\"districtStat\"><b>${standingLabel(faction(state.city==='gotham'?'gcpd':'public'))}</b><span>${state.city==='gotham'?'GCPD':'Public'}</span></div></div></div>${sh}${state.lastResult?`<div class=\"section\"><div class=\"result\">${state.lastResult}</div></div>`:''}<div class=\"section\"><div class=\"sectionTitle\"><h2>District Operations</h2><span>You choose the purpose</span></div><div class=\"operationGrid\"><button class=\"operation\" data-district-action=\"scout\"><strong>Scout</strong><p>Gain district intel. Never secretly turns into combat.</p></button><button class=\"operation\" data-district-action=\"confront\"><strong>Confront Trouble</strong><p>Choose a fight deliberately from this district’s enemy pool.</p></button><button class=\"operation\" data-district-action=\"contact\"><strong>Seek Contact</strong><p>Find a named character here, not a random enemy.</p></button><button class=\"operation\" data-district-action=\"search\"><strong>Search</strong><p>Look for objects or evidence instead of combat.</p></button></div></div><div class=\"section\"><div class=\"grid two\"><button class=\"btn\" data-backcity>Change District</button><button class=\"btn\" data-home>Return to Archive</button></div></div>`}")
replace_line('function bindCommon(){',"function bindCommon(){document.querySelectorAll('[data-go=\"portal\"]').forEach(b=>b.onclick=()=>{state.screen='portal';render()});document.querySelectorAll('[data-universe]').forEach(b=>b.onclick=()=>{state.universe='dc';state.screen='city';state.city=state.city||'gotham';state.location=null;render()});document.querySelectorAll('[data-location]').forEach(b=>b.onclick=()=>{state.location=b.dataset.location;state.screen='location';state.lastResult='';ensureSituation();render()});document.querySelectorAll('[data-switchcity]').forEach(b=>b.onclick=()=>{state.city=state.city==='gotham'?'metropolis':'gotham';state.location=null;state.screen='city';render()});document.querySelectorAll('[data-backcity]').forEach(b=>b.onclick=()=>{state.screen='city';state.location=null;state.lastResult='';render()});document.querySelectorAll('[data-home]').forEach(b=>b.onclick=goHome);document.querySelectorAll('[data-rest]').forEach(b=>b.onclick=()=>{state.player.hp=state.player.hpMax;state.claimEnergy=state.claimEnergyMax;toast('Fully stabilized');render()});document.querySelectorAll('[data-nav]').forEach(b=>b.onclick=()=>openPanel(b.dataset.nav));document.querySelectorAll('[data-situation]').forEach(b=>b.onclick=()=>resolveSituationChoice(b.dataset.situation,b.dataset.choice));document.querySelectorAll('[data-district-action]').forEach(b=>b.onclick=()=>districtAction(b.dataset.districtAction));document.querySelectorAll('[data-upgrades]').forEach(b=>b.onclick=upgradePanel);document.querySelectorAll('[data-customize]').forEach(b=>b.onclick=customizePanel);document.querySelectorAll('[data-newgame]').forEach(b=>b.onclick=newGamePanel)}")
replace_line('function goHome(){',"function goHome(){clearTimeout(autoTimer);state.screen='archive';state.city=null;state.location=null;state.lastResult='';state.encounterMeter=0;state.battle=null;recoveryOnReturn();log('Returned to the Archive.');render()}")
insert_after('function goHome(){',"function districtAction(kind){const l=CITY[state.city].locations[state.location],d=districtState();if(kind==='scout'){d.intel=clamp(d.intel+1,0,5);awardRes(2);state.lastResult='<span class=\"tag\">Scouting</span>You improve your read of this district without rolling a hidden fight.';save();return render()}if(kind==='confront'){const n=d.heat>=4?2:1,en=[];for(let i=0;i<n;i++){let id=rand(l.pool);if(n>1&&TEMPLATES[id].rarity==='Boss')id=rand(l.pool.filter(x=>TEMPLATES[x].rarity!=='Boss'));en.push(id)}return encounterCombat(en,{type:'district'})}if(kind==='contact'){return l.npcs.length?encounterNPC(rand(l.npcs)):(state.lastResult='<span class=\"tag\">Contact</span>No named contact is available here.',render())}if(kind==='search'){if(chance(.55))return itemEvent(l);d.intel=clamp(d.intel+1,0,5);addDisc('search_'+uid(),'Search lead: '+l.name,'Local Intel');state.lastResult='<span class=\"tag\">Search</span>You find usable evidence instead of a fight.';save();return render()}}")
replace_line('function openNPC(id,qid){',"function openNPC(id,qid){const n=NPCS[id],q=qid&&QUESTS[qid],qs=qid&&questState(qid),trust=relation(id);let qBlock='';if(q){if(qs.status==='inactive')qBlock=`<div class=\"dialogue\"><strong>${q.name}</strong><br>${q.desc}</div><div class=\"miniBtns\"><button class=\"miniBtn active\" data-acceptq=\"${qid}\">Accept Quest</button></div>`;else if(qs.status==='active')qBlock=`<div class=\"dialogue\"><strong>Quest active: ${q.name}</strong><br>${currentObjective(qid)}</div>`;else qBlock=`<div class=\"dialogue\"><strong>${q.name} — complete</strong></div>`}const d=sheet('Character Encounter');d.querySelector('.sheet').insertAdjacentHTML('beforeend',`<div class=\"npcRow\"><div class=\"npcPortrait\">${n.icon}</div><div><h3>${n.name}</h3><p>${n.role}</p><span class=\"pill ${trust>=12?'good':trust<=-12?'danger':''}\">${standingLabel(trust)} ${trust>0?'+':''}${trust}</span></div></div><div class=\"dialogue\">${n.intro}<br><br><strong>${rand(n.lines)}</strong></div>${qBlock}<div class=\"miniBtns\"><button class=\"miniBtn\" data-npcintel>Trade information</button><button class=\"miniBtn\" data-npcleave>Leave</button></div>`);d.querySelectorAll('[data-acceptq]').forEach(b=>b.onclick=()=>{startQuest(b.dataset.acceptq);questProgress('talk_'+id);adjustRelation(id,3);d.remove();render()});d.querySelectorAll('[data-npcintel]').forEach(b=>b.onclick=()=>{addDisc('npc_'+id+'_'+state.discoveries.length,'Intel from '+n.name,'Character Intel');adjustRelation(id,1);save();toast(n.name+' trust +1');d.remove();openNPC(id,qid)});d.querySelectorAll('[data-npcleave]').forEach(b=>b.onclick=()=>{d.remove();state.lastResult=`<span class=\"tag\">Named Encounter</span>You met <strong>${n.name}</strong>. Relationship: ${standingLabel(relation(id))}.`;render()})}")
replace_line('function encounterCombat(ids){',"function encounterCombat(ids,context=null){resetPressure();state.stats.encounters++;const totals={};state.squad.forEach(id=>totals[id]=(totals[id]||0)+1);const seen={};const manifests=state.squad.map(id=>{seen[id]=(seen[id]||0)+1;const f=fighterFromTemplate(id,'ally');if(totals[id]>1)f.name+=` #${seen[id]}`;return f});const team=[jonFighter(),...manifests],enemies=ids.map(id=>fighterFromTemplate(id,'enemy'));state.battle={id:uid(),team,enemies,round:1,tactic:'balanced',running:false,speed:1,log:`Hostiles detected: <strong>${enemies.map(e=>e.name).join(', ')}</strong>.`,result:null,claimed:[],defeated:[],context};state.screen='combat';log('Combat encounter: '+enemies.map(e=>e.name).join(', ')+'.');save();render()}")
replace_line('function unitCard(c){',"function unitCard(c){const load=c.side==='ally'&&c.form==='manifest'?`<span class=\"loadBadge\">${manifestCost(c.templateId)} CAP</span>`:'';return `<div class=\"unit ${c.side==='enemy'?'enemy':'hero'} ${c.hp<=0?'dead':''}\"><div class=\"unitVisual\">${combatSprite(c)}</div><div class=\"unitName\"><div><strong>${c.name}</strong><div class=\"unitStats\"><span>ATK ${c.atk}</span><span>DEF ${c.def}</span><span>SPD ${c.spd}</span></div></div><div class=\"unitMeta\">${load}<span>${c.form==='jon'?'JON':c.form==='transform'?'TRANSFORM':c.side==='enemy'?(TEMPLATES[c.templateId]?.rarity||'HOSTILE'):'MANIFEST'}</span></div></div>${hpUI(c)}</div>`}")
replace_line('function actMove(actor,target,id){',"function actMove(actor,target,id){const m=MOVES[id];if(!m||!target)return '';actor.anim='attack';target.anim='hit';if(actor.status.stun>0&&chance(.55)){actor.status.stun--;return `${actor.name} is stunned.`}if(target.evade>0&&chance(.36)){target.evade--;return `${target.name} evades ${m.name}.`}if(Math.random()*100>m.acc)return `${actor.name}'s ${m.name} misses.`;if(m.effect==='guard'){actor.guard=1;return `${actor.name} guards.`}if(m.effect==='guardStrong'){actor.guard=2;return `${actor.name} braces behind heavy protection.`}if(m.effect==='evade'){actor.evade=2;return `${actor.name} shifts into concealment.`}const dmg=moveDamage(actor,target,m);target.hp=Math.max(0,target.hp-dmg);let s=`${actor.name} → <strong>${m.name}</strong> (${dmg})`;if(m.status&&chance(m.statusChance)){target.status[m.status]=m.status==='bleed'?3:2;s+=` · ${m.status}`;}return s}")
replace_line('function runAutoRound(){',"function runAutoRound(){const b=state.battle;if(!b||b.result)return;[...b.team,...b.enemies].forEach(x=>x.anim='');let actors=[...living(b.team),...living(b.enemies)].sort((a,c)=>c.spd-a.spd),lines=[];for(const actor of actors){if(actor.hp<=0)continue;const target=chooseTarget(actor);if(!target)break;const move=chooseMove(actor,actor.side==='enemy'?'balanced':b.tactic);const txt=actMove(actor,target,move);if(txt)lines.push(txt);if(target.hp<=0){lines.push(`<strong>${target.name} is down.</strong>`);if(target.side==='enemy')b.defeated.push(target.templateId)}if(!living(b.enemies).length||!living(b.team).length)break}for(const c of [...b.team,...b.enemies]){const t=tickStatus(c);if(t)lines.push(t)}b.log=lines.join('<br>')||'The teams reposition.';b.round++;checkBattleEnd();save()}")
replace_line('function checkBattleEnd(){',"function checkBattleEnd(){const b=state.battle;if(!living(b.enemies).length){b.result='victory';b.running=false;state.stats.wins++;const unique=[...new Set(b.enemies.map(e=>e.templateId))];const reward=unique.reduce((n,id)=>n+8+Math.floor(TEMPLATES[id].cost*.35),0);awardRes(reward);const jon=b.team.find(x=>x.uid==='jon');if(jon){const ratio=jon.hp/jon.maxHp;state.player.hp=Math.max(1,Math.round(state.player.hpMax*ratio))}const map={blackMaskEnforcer:'beat_blackmask',penguinGunman:'beat_penguin',electrocutioner:'beat_electrocutioner',intergangHeavy:'beat_intergangheavy',lexDrone:'beat_lexdrone'};unique.forEach(id=>{if(map[id])questProgress(map[id])});if(b.context?.type==='situation')resolveSituationCombat(b.context,true);if(b.context?.type==='district')districtState().heat=clamp(districtState().heat-1,0,5);log('Victory over '+unique.map(id=>TEMPLATES[id].name).join(', ')+'.');return}if(!living(b.team).length){b.result='defeat';b.running=false;state.stats.losses++;state.resonance=Math.max(0,state.resonance-10);state.player.hp=1;if(b.context?.type==='situation')resolveSituationCombat(b.context,false);if(b.context?.type==='district')districtState().heat=clamp(districtState().heat+1,0,5);log('Combat defeat.')}}")
replace_line('function finishBattle(){',"function finishBattle(){const b=state.battle,defeated=[...new Set(b.enemies.map(e=>TEMPLATES[e.templateId].name))],r=b.context?.resolutionText;state.battle=null;state.screen='location';state.lastResult=r?`<span class=\"tag\">Situation Resolved</span>${r}`:`<span class=\"tag\">Combat Victory</span>Your team defeated <strong>${defeated.join(', ')}</strong>.`;render()}")

insert_before("function sheet(title,sub=''){",r'''function upgradePanel(){const d=sheet('Upgrade Archive','One permanent resource: Resonance. Each room changes a real system.');Object.entries(ARCHIVE_UPGRADES).forEach(([id,x])=>{const l=archiveLevel(id),c=l<x.max?x.costs[l]:null;d.querySelector('.sheet').insertAdjacentHTML('beforeend',`<div class="upgradeCard"><div class="roomGlyph">${x.glyph}</div><strong>${x.name} · Lv ${l}/${x.max}</strong><p>${x.desc}</p><div class="upgradeEffect">${x.effect(l)}${l<x.max?` → ${x.effect(l+1)}`:' · MAX'}</div><button class="miniBtn ${c!==null&&state.resonance>=c?'active':''}" data-buyupgrade="${id}" ${c===null?'disabled':''}>${c===null?'Maxed':'Upgrade · '+c+' R'}</button></div>`)});d.querySelectorAll('[data-buyupgrade]').forEach(b=>b.onclick=()=>{const id=b.dataset.buyupgrade,before=archiveLevel(id);buyArchiveUpgrade(id);if(archiveLevel(id)!==before){d.remove();upgradePanel();render()}})}
function customizePanel(){const d=sheet('Customize','Cosmetics stay cosmetic. They do not compete with good gear.');d.querySelector('.sheet').insertAdjacentHTML('beforeend',`<div class="avatarPreview">${combatSprite({uid:'jon',form:'jon',side:'ally',templateId:null})}</div><div class="cosmeticGroup"><strong>Outfit</strong><div class="swatches">${Object.entries(OUTFITS).map(([id,n])=>`<button class="swatch ${state.cosmetics.outfit===id?'active':''}" data-outfit="${id}">${n}</button>`).join('')}</div></div><div class="cosmeticGroup"><strong>Accent</strong><div class="swatches">${Object.keys(ACCENTS).map(id=>`<button class="swatch ${state.cosmetics.accent===id?'active':''}" data-accent="${id}">${id}</button>`).join('')}</div></div><div class="cosmeticGroup"><strong>Hair</strong><div class="swatches">${Object.keys(HAIRS).map(id=>`<button class="swatch ${state.cosmetics.hair===id?'active':''}" data-hair="${id}">${id}</button>`).join('')}</div></div><div class="sep"></div><div class="cosmeticGroup"><strong>Archive Theme</strong><div class="grid two">${Object.entries(ARCHIVE_THEMES).map(([id,t])=>{const ok=t.need();return `<button class="choice ${ok?'':'locked'}" data-theme="${id}" ${!ok?'disabled':''}><div class="themePreview archiveTheme-${id}"></div><strong>${t.name}</strong><p>${ok?'Apply theme':'Unlock through its Archive room.'}</p></button>`}).join('')}</div></div>`);const rr=()=>{save();d.remove();customizePanel();render()};d.querySelectorAll('[data-outfit]').forEach(b=>b.onclick=()=>{state.cosmetics.outfit=b.dataset.outfit;rr()});d.querySelectorAll('[data-accent]').forEach(b=>b.onclick=()=>{state.cosmetics.accent=b.dataset.accent;rr()});d.querySelectorAll('[data-hair]').forEach(b=>b.onclick=()=>{state.cosmetics.hair=b.dataset.hair;rr()});d.querySelectorAll('[data-theme]').forEach(b=>b.onclick=()=>{const id=b.dataset.theme;if(ARCHIVE_THEMES[id].need()){state.archive.theme=id;rr()}})}''')

replace_line('function claimsPanel(){',"function claimsPanel(){const used=manifestUsed(),cap=state.manifestCapacityMax,per=Math.round(used/cap*100),d=sheet('Claim Archive','One living template can manifest repeatedly; capacity controls how many bodies remain stable.');d.querySelector('.sheet').insertAdjacentHTML('beforeend',`<div class=\"capacityCard\"><div class=\"capacityHead\"><div><strong>Manifestation Capacity</strong><div class=\"capacitySub\">${state.squad.length}/${MANIFEST_BODY_LIMIT} bodies active</div></div><b>${used}/${cap}</b></div><div class=\"capacityBar ${per>=85?'warn':''}\"><i style=\"width:${per}%\"></i></div></div>`);if(!state.claims.length)d.querySelector('.sheet').insertAdjacentHTML('beforeend','<div class=\"listItem\"><p>No living templates yet.</p></div>');state.claims.forEach(id=>{const t=TEMPLATES[id],count=manifestCount(id),cost=manifestCost(id),can=canAddManifest(id);d.querySelector('.sheet').insertAdjacentHTML('beforeend',`<div class=\"listItem\"><div class=\"manifestRow\"><div class=\"npcPortrait\">${t.icon}</div><div><strong>${t.name}</strong><span class=\"copyBadge\">×${count}</span><p>${cost} capacity per copy · HP ${t.stats.hp} · ATK ${t.stats.atk} · DEF ${t.stats.def}</p></div></div><div class=\"manifestButtons\"><button class=\"miniBtn remove\" data-squadremove=\"${id}\" ${count<=0?'disabled':''}>−</button><button class=\"miniBtn add\" data-squadadd=\"${id}\" ${!can?'disabled':''}>${can?'Manifest Copy · +'+cost:'Capacity/body limit'}</button></div><div class=\"miniBtns\">${t.moves.map(m=>`<button class=\"miniBtn ${state.channel===m?'active':''}\" data-channel=\"${m}\">${MOVES[m].name}</button>`).join('')}</div></div>`)});d.querySelector('.sheet').insertAdjacentHTML('beforeend',`<div class=\"sep\"></div><div class=\"listItem\"><strong>Claimed Objects · ${state.equippedItems.length}/${itemSlotMax()} equipped</strong></div>`);state.itemClaims.forEach(id=>{const it=CLAIM_ITEMS[id],on=state.equippedItems.includes(id);d.querySelector('.sheet').insertAdjacentHTML('beforeend',`<div class=\"listItem\"><strong>${it.name}</strong><p>${it.desc}</p><button class=\"miniBtn ${on?'active':''}\" data-equipitem=\"${id}\">${on?'Unequip':'Equip Manifested Copy'}</button></div>`)});d.querySelectorAll('[data-squadadd]').forEach(b=>b.onclick=()=>{const id=b.dataset.squadadd;if(!canAddManifest(id))return toast('Not enough Manifestation Capacity');state.squad.push(id);save();d.remove();claimsPanel()});d.querySelectorAll('[data-squadremove]').forEach(b=>b.onclick=()=>{const i=state.squad.lastIndexOf(b.dataset.squadremove);if(i>=0)state.squad.splice(i,1);save();d.remove();claimsPanel()});d.querySelectorAll('[data-channel]').forEach(b=>b.onclick=()=>{state.channel=b.dataset.channel;save();d.remove();claimsPanel()});d.querySelectorAll('[data-equipitem]').forEach(b=>b.onclick=()=>{const id=b.dataset.equipitem;if(state.equippedItems.includes(id))state.equippedItems=state.equippedItems.filter(x=>x!==id);else if(state.equippedItems.length<itemSlotMax())state.equippedItems.push(id);else return toast(itemSlotMax()+' item slots max');save();d.remove();claimsPanel()})}")
replace_line('function bagPanel(){',"function bagPanel(){const d=sheet('Gear & Archive Data','Your loadout, influence, and recent activity.');Object.entries(ITEMS).forEach(([id,it])=>d.querySelector('.sheet').insertAdjacentHTML('beforeend',`<div class=\"listItem\"><strong>${it.name} × ${state.inventory[id]||0}</strong><p>${it.desc}</p>${id!=='smokeCharge'?`<button class=\"miniBtn\" data-useout=\"${id}\" ${(state.inventory[id]||0)<=0?'disabled':''}>Use Now</button>`:''}</div>`));d.querySelector('.sheet').insertAdjacentHTML('beforeend',`<div class=\"sep\"></div><div class=\"listItem\"><strong>Influence</strong><div style=\"margin-top:8px\">${factionStrip()}</div></div><div class=\"listItem\"><strong>Recent Activity</strong><p>${state.feed.slice(0,8).map(x=>'• '+x.text).join('<br>')}</p></div><div class=\"miniBtns\"><button class=\"miniBtn\" data-upgrades>Upgrade Archive</button><button class=\"miniBtn\" data-customize>Customize</button><button class=\"miniBtn\" data-newgame>Start New Game</button></div>`);d.querySelectorAll('[data-useout]').forEach(b=>b.onclick=()=>{const id=b.dataset.useout;if((state.inventory[id]||0)<=0)return;state.inventory[id]--;if(id==='medPatch')state.player.hp=Math.min(state.player.hpMax,state.player.hp+35);if(id==='focusCell')state.claimEnergy=Math.min(state.claimEnergyMax,state.claimEnergy+30);save();d.remove();bagPanel()});d.querySelectorAll('[data-upgrades]').forEach(b=>b.onclick=()=>{d.remove();upgradePanel()});d.querySelectorAll('[data-customize]').forEach(b=>b.onclick=()=>{d.remove();customizePanel()});d.querySelectorAll('[data-newgame]').forEach(b=>b.onclick=()=>{d.remove();newGamePanel()})}")
replace_line('function newGamePanel(){',"function newGamePanel(){const d=sheet('Start New Game','This permanently erases this local save, including Archive upgrades, relationships, cosmetics, and world decisions.');d.querySelector('.sheet').insertAdjacentHTML('beforeend',`<div class=\"card systemCard\"><strong>Fresh Archive</strong><p class=\"tip\">Restart with the empty Old Library and default Jon appearance.</p><button class=\"btn danger\" data-confirmnew style=\"margin-top:10px\">Erase Save & Start New Game</button></div>`);d.querySelector('[data-confirmnew]').onclick=()=>{clearTimeout(autoTimer);try{localStorage.removeItem(KEY)}catch(e){}state=fresh();save();d.remove();render();toast('New game started')}}")

